schema_name = os.environ['MLPAB_DATABRICKS_SCHEMA']
table_name = 'scaled290b1e'
full_table_name = f'{schema_name}.{table_name}'

# Register the feature table using the Feature Store API
ft = w.api_client.do(
    method='POST',
    path='/api/2.0/feature-engineering/tables',
    body={
        'name': full_table_name,
        'primary_keys': ['row_id'],
        'schema': [
            {'name': 'row_id', 'type': 'STRING'},
            {'name': 'split', 'type': 'STRING'},
            {'name': 'f1', 'type': 'DOUBLE'},
            {'name': 'f2', 'type': 'DOUBLE'},
            {'name': 'f3', 'type': 'DOUBLE'},
            {'name': 'f4', 'type': 'DOUBLE'}
        ],
        'delta_table': {
            'delta_table_name': full_table_name
        },
        'online_store_spec': {
            'online_store_type': 'DELTASHARING'
        }
    }
)

print(f'Feature table {full_table_name} registered successfully.')
print(f'Feature table ID: {ft[\"table_id\"]}')

# Enable online access
w.api_client.do(
    method='POST',
    path=f'/api/2.0/feature-engineering/tables/{ft[\"table_id\"]}/online-store',
    body={
        'online_store_spec': {
            'online_store_type': 'DELTASHARING'
        }
    }
)

print(f'Online access enabled for feature table {full_table_name}.')
